package io.knowledgebrain.learning;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.serialization.*;import org.flywaydb.core.Flyway;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;
import io.knowledgebrain.contracts.learning.publicroadmap.v1.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP",matches=".+")
class PublicRoadmapKafkaIntegrationTest {
 @Test void twoPublicTopicsCarryOnlyExplicitGraphAndExactCommittedBytes()throws Exception{
  var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();var store=new PublicRoadmapStore(ds,Clock.systemUTC());var ids=new UuidV7(Clock.systemUTC());var space=ids.next();var actor=ids.next();var reviewer=ids.next();String trace="d".repeat(32);
  var p=store.submit(space,actor,null,0,"Kafka public","Explicit graph only","Reason",PublicRoadmapStoreIntegrationTest.graph(),trace);store.review(space,p.contributionId(),reviewer,1,"APPROVED","Checked",trace);store.merge(space,p.contributionId(),reviewer,2,trace);
  var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregateid IN (?,?)",(rs,n)->Map.entry(rs.getObject(1,UUID.class).toString(),rs.getBytes(2)),p.contributionId(),p.roadmapId()).forEach(e->expected.put(e.getKey(),e.getValue()));assertEquals(4,expected.size());
  var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_LEARNING_KAFKA_BOOTSTRAP"));options.put("group.id","learning-validation-"+ids.next());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/learning-kafka-test/ca.crt")));options.put("ssl.keystore.type","PEM");options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/learning-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/learning-kafka-test/user.key")));

  try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("learning.public-roadmap.v1","learning.roadmap-contribution.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long deadline=System.nanoTime()+Duration.ofSeconds(75).toNanos();while(found.size()<4&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofSeconds(1))){if(!Set.of(p.contributionId().toString(),p.roadmapId().toString()).contains(record.key()))continue;var envelope=PublicRoadmapEnvelopeV1.parseFrom(record.value());assertArrayEquals(expected.get(envelope.getEventId()),record.value());assertEquals(space.toString(),envelope.getSpaceId());assertEquals(trace,envelope.getTraceId());assertEquals(1,envelope.getEventVersion());assertEquals("learning-service",envelope.getProducer());assertEquals(7,UUID.fromString(envelope.getEventId()).version());String artifact;if(record.topic().equals("learning.public-roadmap.v1")){artifact="public-roadmap-events";assertEquals("PublicRoadmap",envelope.getAggregateType());var snapshot=PublicRoadmapChangedV1.parseFrom(envelope.getPayload()).getSnapshot();assertEquals("PUBLIC",snapshot.getVisibility());assertEquals("REVIEWED",snapshot.getVerification());assertEquals(2,snapshot.getNodesCount());assertEquals(1,snapshot.getEdgesCount());assertEquals(reviewer.toString(),envelope.getActorId());}else{artifact="roadmap-contribution-events";assertEquals("RoadmapContribution",envelope.getAggregateType());var snapshot=RoadmapContributionChangedV1.parseFrom(envelope.getPayload());assertEquals(2,snapshot.getNodesCount());assertEquals(1,snapshot.getEdgesCount());if(found.add(envelope.getEventId()))versions.add(snapshot.getVersion());}for(var pair:Map.of("trace_id",trace,"schema_group","learning","schema_artifact",artifact,"schema_version","1").entrySet()){assertNotNull(record.headers().lastHeader(pair.getKey()));assertEquals(pair.getValue(),new String(record.headers().lastHeader(pair.getKey()).value(),StandardCharsets.UTF_8));}found.add(envelope.getEventId());}assertEquals(expected.keySet(),found);assertEquals(List.of(1L,2L,3L),versions);}
 }
}
